{"command":"cat <<'EOF' > solve_clique.py
import itertools
from typing import List, Dict, Any
from problems import Clique

def has_clique(instance: Dict[str, Any]) -> bool:
    Clique.validate(instance)
    n = instance['n']
    edges = set()
    for u, v in instance['edges']:
        if u > v:
            u, v = v, u
        edges.add((u, v))
    k = instance['k']
    if k <= 0:
        return True
    if k == 1:
        return n >= 1
    if k > n:
        return False
    # brute force check subsets of size k
    for subset in itertools.combinations(range(n), k):
        ok = True
        for i in range(k):
            for j in range(i+1, k):
                a, b = subset[i], subset[j]
                if a > b:
                    a, b = b, a
                if (a, b) not in edges:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            return True
    return False
EOF"}

